<?php
namespace App\Repositories;
use App\Models\Sponsor;use Illuminate\Contracts\Pagination\LengthAwarePaginator;use Illuminate\Database\Eloquent\Builder;use Illuminate\Support\Facades\Cache;
class SponsorRepository{public function search(array $filters,int $perPage=20):LengthAwarePaginator{$q=Sponsor::query();$term=trim((string)($filters['q']??''));if($term!==''){$q->where(function(Builder $b)use($term){$b->whereFullText(['company_name','town','county','postcode','licence_number','organisation_type'],$term)->orWhere('company_name','like',"%$term%")->orWhere('postcode','like',"%$term%");});}foreach(['town','county','rating','status'] as $f){if(!empty($filters[$f])){$q->where($f,$filters[$f]);}}if(!empty($filters['route'])){$q->whereJsonContains('routes',$filters['route']);}return $q->orderBy($filters['sort']==='newest'?'imported_at':'company_name',$filters['sort']==='newest'?'desc':'asc')->paginate($perPage)->withQueryString();}public function statistics():array{return Cache::remember('statistics',300,fn()=>['total_sponsors'=>Sponsor::count(),'total_routes'=>Sponsor::query()->selectRaw('COUNT(DISTINCT JSON_EXTRACT(routes, "$[*]")) as c')->value('c')??0,'latest_import'=>Sponsor::max('imported_at')]);}}
